--
-- Table structure for table `pricing_history`
--

DROP TABLE IF EXISTS `pricing_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pricing_history` (
  `pricing_id` int NOT NULL AUTO_INCREMENT,
  `product_id` int NOT NULL,
  `branch_id` int DEFAULT NULL,
  `wholesale_price` decimal(10,2) DEFAULT NULL,
  `quantity` int DEFAULT NULL,
  `suggested_price` decimal(10,2) DEFAULT NULL,
  `applied_price` decimal(10,2) DEFAULT NULL,
  `ai_reasoning` text,
  `suggested_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `suggested_by` int DEFAULT NULL,
  PRIMARY KEY (`pricing_id`),
  KEY `product_id` (`product_id`),
  KEY `branch_id` (`branch_id`),
  KEY `suggested_by` (`suggested_by`),
  CONSTRAINT `pricing_history_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pricing_history_ibfk_2` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pricing_history_ibfk_3` FOREIGN KEY (`suggested_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=241 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

